			closedWindows.clear();
			for (Lwjgl3Window window : windows) {
				Gdx.graphics = window.getGraphics();
				Gdx.gl30 = window.getGraphics().getGL30();
				Gdx.gl20 = Gdx.gl30 != null ? Gdx.gl30 : window.getGraphics().getGL20();
